import worker, threading, time

def race(n):
    pool = worker.Pool()
    for j in range(50):
        pool.submit("job%d" % j)
    results = {"c": [], "h": []}
    errors = []

    def claimer():
        try:
            for i in range(50):
                results["c"].append(pool.claim("w%d" % i))
        except Exception as e:
            errors.append(("claimer", repr(e)))

    def hander():
        try:
            for i in range(50):
                results["h"].append(pool.handoff("w%d" % i, {"i": i}))
        except Exception as e:
            errors.append(("hander", repr(e)))

    ts = [threading.Thread(target=claimer) for _ in range(4)] + \
         [threading.Thread(target=hander) for _ in range(4)]
    start = time.monotonic()
    for t in ts: t.start()
    for t in ts: t.join(timeout=5)
    alive = [t.is_alive() for t in ts]
    print("run %d: elapsed=%.2fs alive_threads=%d errors=%s claimed=%d handed=%d"
          % (n, time.monotonic()-start, sum(alive), errors,
             len([x for x in results["c"] if x is not None]),
             len([x for x in results["h"] if x is not None])))
    return alive

for i in range(10):
    if any(race(i)):
        print("=> DEADLOCK at iteration", i)
        break
