import worker, threading, time, random

# Same race pattern as before, but this time both threads can interleave:
# claim() holds _queue_lock while handoff() holds _report_lock and then
# requests _queue_lock.
def race(n):
    pool = worker.Pool()
    for j in range(200):
        pool.submit("job%d" % j)
    claimed = []
    handed = []
    errors = []

    def claimer():
        try:
            while True:
                j = pool.claim("c")
                if j is None:
                    break
                claimed.append(j)
                time.sleep(random.random() * 0.001)
        except Exception as e:
            errors.append(("claimer", repr(e)))

    def hander():
        try:
            while True:
                j = pool.handoff("h", {"r": 1})
                if j is None:
                    break
                handed.append(j)
                time.sleep(random.random() * 0.001)
        except Exception as e:
            errors.append(("hander", repr(e)))

    ts = [threading.Thread(target=claimer) for _ in range(8)] + \
         [threading.Thread(target=hander) for _ in range(8)]
    start = time.monotonic()
    for t in ts: t.start()
    for t in ts: t.join(timeout=5)
    alive = sum(1 for t in ts if t.is_alive())
    ok = alive == 0 and not errors and (len(claimed) + len(handed)) == 200
    print("run %d: alive=%d errors=%s claimed=%d handed=%d -> %s"
          % (n, alive, errors, len(claimed), len(handed), "OK" if ok else "FAIL"))
    return alive or errors or (len(claimed) + len(handed)) != 200

bad = 0
for i in range(50):
    if race(i):
        bad += 1
print("failed iterations:", bad)
