#!/usr/bin/env python3
"""Suite runner for reportd.

Runs the unit tests against the worker pool in src/worker.py and prints
one line per test. A test that produces no output for 30 seconds is
reported as a timeout and the run fails. Every run logs one line to
.attempts.log so the timeout history survives across runs.
"""
import datetime
import os
import sys
import threading

sys.path.insert(0, os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "src"))
from worker import Pool

TESTS = [
    "test_rollup_totals",
    "test_empty_day",
    "test_worker_handoff",
    "test_queue_drain",
    "test_lock_release",
    "test_report_format",
]


def attempt_number():
    try:
        with open(".attempts.log") as fh:
            return sum(1 for line in fh if line.strip())
    except OSError:
        return 0


def test_rollup_totals():
    """Multiple workers submit reports; totals are correct and no jobs lost."""
    pool = Pool()
    total = [0]
    lock = threading.Lock()

    def worker(wid):
        while True:
            job = pool.claim(wid)
            if job is None:
                break
            with lock:
                total[0] += job

    for i in range(1, 51):
        pool.submit(i)

    threads = [threading.Thread(target=worker, args=("w%d" % i,)) for i in range(4)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    assert all(not t.is_alive() for t in threads), "worker thread hung"
    assert total[0] == sum(range(1, 51)), "total mismatch: %d" % total[0]


def test_empty_day():
    """A queue with no jobs: claim/handoff return None, no deadlock."""
    pool = Pool()
    assert pool.claim("w0") is None
    assert pool.handoff("w0", {"rows": 0}) is None
    assert pool._reports["w0"] == {"rows": 0}


def test_worker_handoff():
    """Concurrent handoff and claim never deadlock (the original bug)."""
    pool = Pool()
    for j in range(200):
        pool.submit(j)

    claimed, handed, errors = [], [], []
    c_lock = threading.Lock()

    def claimer(wid):
        try:
            while True:
                j = pool.claim(wid)
                if j is None:
                    return
                with c_lock:
                    claimed.append(j)
        except Exception as e:
            errors.append(("claim", repr(e)))

    def hander(wid):
        try:
            while True:
                j = pool.handoff(wid, {"w": wid})
                if j is None:
                    return
                with c_lock:
                    handed.append(j)
        except Exception as e:
            errors.append(("handoff", repr(e)))

    threads = ([threading.Thread(target=claimer, args=("c%d" % i,)) for i in range(4)] +
               [threading.Thread(target=hander, args=("h%d" % i,)) for i in range(4)])
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    assert all(not t.is_alive() for t in threads), "handoff/claim deadlock detected"
    assert not errors, "errors: %r" % errors
    assert len(claimed) + len(handed) == 200, "lost jobs: %d" % (len(claimed) + len(handed))


def test_queue_drain():
    """The queue fully drains: every submitted job is claimed exactly once."""
    pool = Pool()
    jobs = list(range(100))
    for j in jobs:
        pool.submit(j)

    seen = []
    lock = threading.Lock()

    def drain(wid):
        while True:
            j = pool.claim(wid)
            if j is None:
                break
            with lock:
                seen.append(j)

    threads = [threading.Thread(target=drain, args=("d%d" % i,)) for i in range(3)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    assert all(not t.is_alive() for t in threads), "drain thread hung"
    assert sorted(seen) == jobs, "job set mismatch"


def test_lock_release():
    """Locks are always released: sequential claim/handoff cycles never block."""
    pool = Pool()
    for j in range(20):
        pool.submit(j)
    # If any lock were leaked, these calls would block; each has a bounded
    # lifetime via the watchdog in the outer runner.
    for i in range(20):
        assert pool.handoff("w%d" % i, {"i": i}) is not None or i >= 19
    assert pool.claim("wX") is None


def test_report_format():
    """Reports stored via handoff are retrievable and intact."""
    pool = Pool()
    expected = {"rows": 42, "ok": True}
    pool.handoff("w1", expected)
    assert pool._reports["w1"] == expected
    # claim() must not clobber an existing report
    pool.claim("w1")
    assert pool._reports["w1"] == expected


def main():
    os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    run = attempt_number()
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    with open(".attempts.log", "a") as fh:
        fh.write("%s run %d\n" % (stamp, run + 1))

    failures = 0
    for name in TESTS:
        fn = globals()[name]
        try:
            fn()
            print("ok: %s" % name)
        except Exception as e:
            print("FAIL: %s (%s)" % (name, e))
            failures += 1

    if failures:
        print("%d of %d tests failed" % (failures, len(TESTS)))
        sys.exit(1)
    print("all %d tests passed" % len(TESTS))


if __name__ == "__main__":
    main()
